-- Keep numeric geometry packed until requested. At most two map buckets are
-- expanded; eviction drops only our reference, never mutates a caller's rows.
local recent = {}
local bucketMeta = { __index = function(bucket, key)
    if key ~= "overlays" then return nil end
    local overlays = {}
    for row in bucket.packed:gmatch("[^\r\n]+") do
        local values, tiles, index = {}, {}, 0
        for number in row:gmatch("%-?%d+") do
            index = index + 1
            if index <= 6 then values[index] = tonumber(number)
            else tiles[#tiles + 1] = tonumber(number) end
        end
        if index > 0 then values[7] = tiles; overlays[#overlays + 1] = values end
    end
    rawset(bucket, "overlays", overlays)
    if #recent == 2 then rawset(table.remove(recent, 1), "overlays", nil) end
    recent[#recent + 1] = bucket
    return overlays
end }
for _, bucket in pairs(ns.MapRevealData.arts) do setmetatable(bucket, bucketMeta) end
